-- Management insight queries
SELECT Category, ROUND(SUM(Revenue),2) AS revenue, ROUND(SUM(Profit)/NULLIF(SUM(Revenue),0)*100,2) AS margin_pct FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY Category HAVING SUM(Revenue) > 500000 ORDER BY margin_pct ASC;
WITH regional AS (SELECT Region, SUM(Revenue) AS revenue, SUM(Profit)/NULLIF(SUM(Revenue),0) AS margin FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY Region), benchmarks AS (SELECT AVG(revenue) AS avg_revenue, AVG(margin) AS avg_margin FROM regional) SELECT r.* FROM regional r CROSS JOIN benchmarks b WHERE r.revenue > b.avg_revenue AND r.margin < b.avg_margin ORDER BY r.revenue DESC;
WITH monthly AS (SELECT DATE_TRUNC('month', Order_Date) AS month, SUM(Revenue) AS revenue FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY 1) SELECT month, ROUND(revenue,2) AS revenue, ROUND((revenue-LAG(revenue) OVER (ORDER BY month))/NULLIF(LAG(revenue) OVER (ORDER BY month),0)*100,2) AS mom_growth_pct FROM monthly ORDER BY month;
